 * - .nimbus/artifacts/analyze-auth-flow/internal_posts_id.json (auth_type: none, no interceptors)
 * - .nimbus/artifacts/detect-external-calls/CommunityController_getPost.json (external_calls: [] -> no WireMock stub needed)
