        String id = testId(info);
        Map<String, String> data = params(
                "ID", id,
                "USER_ID", id + "-user",
                "TITLE", "Zero Likes Post " + id,
                "CATEGORY", "daily",
                "CONTENT", "Freshly created content for " + id,
                "MOOD_EMOJI", "'🙂'",
                "NICKNAME", "nick-" + id,
                "LIKES", "0",
                "CREATED_AT", "2026-02-01 09:00:00");

        executeSqlTemplate("sql/post-by-id-teardown.sql", data);
        executeSqlTemplate("sql/post-by-id-setup.sql", data);

        try {
