        String id = testId(info);
        Map<String, String> data = params(
                "ID", id,
                "USER_ID", id + "-user",
                "TITLE", "No Mood Post " + id,
                "CATEGORY", "mental",
                "CONTENT", "Content without mood emoji for " + id,
                "MOOD_EMOJI", "NULL",
                "NICKNAME", "nick-" + id,
                "LIKES", "2",
                "CREATED_AT", "2026-03-10 18:45:00");

        executeSqlTemplate("sql/post-by-id-teardown.sql", data);
        executeSqlTemplate("sql/post-by-id-setup.sql", data);

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .pathParam("id", id)
