    // ---------------------------------------------------------------------

    @Test
    void VTC_id_WHITE_SPACE(TestInfo info) {
        String whiteSpaceId = "   ";

        given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", whiteSpaceId)
        .when()
                .get("/internal/posts/{id}")
        .then().log().all()
                .statusCode(404)
                .body("type", equalTo("about:blank"))
                .body("title", equalTo("Post not found"))
                .body("status", equalTo(404))
                .body("detail", equalTo(notFoundDetail(whiteSpaceId)));
    }

    @Test
    void VTC_id_SPECIAL_CHAR(TestInfo info) throws Exception {
        String canaryId = testId(info);
        Map<String, String> canary = params(
                "ID", canaryId,
                "USER_ID", canaryId + "-user",
