    // ATC — Exception paths
    // ---------------------------------------------------------------------

    @Test
    void ATC_id_NOT_FOUND(TestInfo info) {
        String missingId = testId(info);

        given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", missingId)
        .when()
                .get("/internal/posts/{id}")
        .then().log().all()
                .statusCode(404)
