                .body("type", equalTo("about:blank"))
                .body("title", equalTo("Post not found"))
                .body("status", equalTo(404))
                .body("detail", equalTo(notFoundDetail(missingId)));
    }

    @Test
    void ATC_wrongMethod_405(TestInfo info) {
        String anyId = testId(info);

        given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", anyId)
        .when()
                .post("/internal/posts/{id}")
        .then().log().all()
                .statusCode(405);
    }
}

